sp_widget.client_script:
api.controller = function() {
    /* widget controller */
    var c = this;

    c.toggleSaved = function(announcement, event) {
        if (event) {
            event.preventDefault();
            event.stopPropagation();
        }

        if (!announcement || !announcement.sys_id || !announcement.tracking)
            return;

        if (announcement._saving)
            return;

        var shouldSave = !announcement.tracking.saved;
        announcement._saving = true;

        c.server.get({
            action: 'toggle_saved',
            communication_id: announcement.sys_id,
            saved: shouldSave

        }).then(function(response) {
            var result = response.data;

            if (result && result.success)
                announcement.tracking.saved = result.saved;

            announcement._saving = false;

        }, function() {
            announcement._saving = false;
        });
    };
};

sp_widget.css:
.aes-announcement-feed__grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  padding: $aes-space-2xl 0;
  gap: $aes-space-3xl $aes-space-xl;
}

.aes-announcement-feed__grid-item {
  min-width: 0;
  box-shadow: $aes-shadow-lg;
}

.aes-announcement-card {
  overflow: hidden;
  background-color: $background-primary;
  border: 1px solid $border-tertiary;
  border-radius: $aes-radius-md;
}

.aes-announcement-card--grid {
  display: flex;
  flex-direction: column;
  height: 100%;
}

.aes-announcement-card__media {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  background-color: $background-secondary;
}

.aes-announcement-card__image {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.aes-announcement-card__new {
  position: absolute;
  top: $aes-space-sm;
  left: $aes-space-sm;

  padding: 2px $aes-space-sm;

  color: $aes-new-color;
  font-size: $font-size-base;
  font-weight: 600;

  background-color: $aes-new-background;
  border-radius: $aes-radius-sm;
}

.aes-announcement-card__body {
  display: flex;
  flex: 1;
  flex-direction: column;
  padding: $aes-space-md $aes-space-xl;
}

.aes-announcement-card__metadata {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: $aes-space-sm;
  min-height: $line-height-base;
  margin: $aes-space-sm 0;
  flex-direction: row-reverse;
}

.aes-announcement-card__category {
  min-height: 1em;
  overflow: hidden;
  color: $text-secondary;
  font-size: $font-size-small;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.aes-announcement-card__urgent {
  flex-shrink: 0;
  padding: 2px $aes-space-sm;
  color: $aes-urgent-color;
  font-size: $font-size-xs;
  font-weight: 600;

  background-color: $aes-urgent-background;
}

.aes-announcement-card__title {
  display: -webkit-box;
  overflow: hidden;
  margin: 0;
  color: $text-primary;
  font-size: $font-size-h4;
  font-weight: 600;
  line-height: $headings-line-height;

  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.aes-announcement-card__description {
  display: -webkit-box;
  overflow: hidden;

  margin: $aes-space-sm 0 0;

  color: $text-secondary;
  font-size: $font-size-base;
  line-height: $line-height-base;

  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.aes-announcement-card__footer {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: $aes-space-xs;
  width: 100%;
  margin-top: auto;
  padding-top: $aes-space-xl;
}

.aes-announcement-card__footer-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: $aes-space-md;

  width: 100%;
}

.aes-announcement-card__date {
  color: $text-tertiary;
  font-size: $font-size-small;;
}

.aes-announcement-card__actions {
  display: flex;
  align-items: center;
}

.aes-announcement-card__action {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  width: 32px;
  height: 32px;
  padding: 0;

  color: $text-secondary;
  background: transparent;
  border: 0;
  border-radius: $aes-radius-sm;

  transition:
    color $aes-transition-fast,
    background-color $aes-transition-fast;
}

.aes-announcement-card__action:hover,
.aes-announcement-card__action:focus {
  color: $text-primary;
  background-color: $background-secondary;
}

.aes-announcement-card__action--active {
  color: $aes-saved-color;
}

.aes-announcement-card__primary-action {
  color: $link-color;
  display: inline-flex;
  align-items: center;
  align-self: flex-start;
  gap: $aes-space-sm;
  font-weight: 600;
  text-decoration: none;
  position: relative;
}

.aes-announcement-card__primary-action::after {
  content: '';
  position: absolute;
  width: 100%;
  height: 2px;
  bottom: -2px;
  left: 0;
  background-color: $aes-accent-hover; 
  transform: scaleX(0);
  transform-origin: bottom right;
  transition: transform 0.3s ease-out;
}

.aes-announcement-card__primary-action:hover {
  cursor: pointer;
  color: $link-hover-color;
}

.aes-announcement-card__primary-action:hover::after ,
.aes-announcement-card__primary-action:focus::after  {
  transform: scaleX(1);
  transform-origin: bottom left;
}

.aes-announcement-card__action .fa-plus {
  transition: transform $aes-transition-fast;
}

.aes-announcement-card__action--open .fa-plus {
  transform: rotate(45deg);
}

@media (max-width: 1200px) {
  .aes-announcement-feed__grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 900px) {
  .aes-announcement-feed__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 600px) {
  .aes-announcement-feed__grid {
    grid-template-columns: 1fr;
  }
}

sp_widget.script:
(function() {
    var portal = $sp.getPortalRecord();

    var resolver = new AESPortalChannelResolver();
    var channelId = resolver.getChannel(
        portal.getUniqueValue()
    );

    if (!channelId) {
        data.announcements = [];
        return;
    }

    if (input && input.action === 'toggle_saved') {
        var tracking = new AESCommunicationTracking();
        var result;

        if (input.saved)
            result = tracking.save(input.communication_id);
        else
            result = tracking.unsave(input.communication_id);

        data.success = result.success;
        data.reason = result.reason || '';
        data.saved = result.success ? !!input.saved : null;

        return;
    }

    var service = new AESAnnouncementService();

    data.announcements = service.getAvailable({
        displayType: 'feed',
        channel: channelId,
        limit: 12,
        offset: 0
    });

})();
